/bin/bash -lc "cat > src/util/ordersApi.mjs <<'EOF'
/**
 * Normalize the backend's order-list response (ReadableOrderList) into
 * a stable shape:
 *   { orders, pages, total, onThisPage }
 *
 * Backend fields (com.salesmanager.shop.model.order.v0.ReadableOrderList
 * and its base ReadableList):
 *   - orders: List<ReadableOrder>
 *   - pageCount: int
 *   - totalRecords: long
 *   - itemsOnPage: int
 */
export function normalizeOrderList(response) {
  const data = (response && typeof response === 'object') ? response : {};

  const orders = Array.isArray(data.orders) ? data.orders : [];
  const pages = Number.isFinite(Number(data.pageCount)) ? Number(data.pageCount) : 0;
  const total = Number.isFinite(Number(data.totalRecords)) ? Number(data.totalRecords) : 0;
  const onThisPage = Number.isFinite(Number(data.itemsOnPage)) ? Number(data.itemsOnPage) : 0;

  return { orders, pages, total, onThisPage };
}
EOF
node --input-type=module -e \"
import { normalizeOrderList } from './src/util/ordersApi.mjs';
console.log(JSON.stringify(normalizeOrderList({orders:[1,2],pageCount:3,totalRecords:12,itemsOnPage:5})));
console.log(JSON.stringify(normalizeOrderList(null)));
console.log(JSON.stringify(normalizeOrderList({orders:'x',pageCount:'2',totalRecords:undefined,itemsOnPage:null})));
\""
